cd /workspace; python3 - <<'EOF'
import json,glob
for f in sorted(glob.glob('experiment_logs/validation/*.jsonl')):
    print('='*30, f)
    for i,l in enumerate(open(f)):
        d=json.loads(l)
        print(f"rec {i}: step={d.get('step')} score={d.get('score')} reward={d.get('reward')} response_length={d.get('response_length')} prompt_len={len(d.get('prompt',''))}")
        print("  gen keys:", list(d.get('generation',{}).keys()) if isinstance(d.get('generation'),dict) else type(d.get('generation')))
        g=d.get('generation')
        if isinstance(g,dict):
            for k,v in g.items():
                if isinstance(v,list):
                    print(f"    {k}: list len {len(v)}")
                else:
                    print(f"    {k}: {repr(v)[:120]}")
        print("  output tail:", repr(d.get('output','')[-200:]))
        print("  prompt:", repr(d.get('prompt','')[:200]))
EOF

